<?php
require __DIR__.'/_init.php';$types=['page'=>'Pages','article'=>'Articles','country'=>'Country guides','review'=>'Reviews','faq'=>'FAQs'];$type=$_GET['type']??'article';if(!isset($types[$type]))$type='article';$id=(int)($_GET['id']??0);$item=null;if($id){$q=db()->prepare('SELECT * FROM content WHERE id=?');$q->execute([$id]);$item=$q->fetch();if(!$item)redirect(url('admin/content.php?type='.$type));$type=$item['type'];}
function slugify_admin(string $s):string{$s=strtolower(trim($s));return trim(preg_replace('/[^a-z0-9]+/','-',$s)??'','-')?:'page';}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='delete'){db()->prepare('DELETE FROM content WHERE id=?')->execute([(int)$_POST['id']]);flash('Content deleted.');redirect(url('admin/content.php?type='.$type));}$title=trim($_POST['title']??'');$slug=slugify_admin(trim($_POST['slug']??'')?:$title);$excerpt=trim($_POST['excerpt']??'');$body=$_POST['body']??'';$image=trim($_POST['image']??'');$author=trim($_POST['author']??'');$status=($_POST['status']??'draft')==='published'?'published':'draft';$sort=(int)($_POST['sort_order']??0);if(!$title){flash('Title is required.');redirect(url('admin/content.php?type='.$type));}try{if($id){$q=db()->prepare('UPDATE content SET title=?,slug=?,excerpt=?,body=?,image=?,author=?,status=?,sort_order=? WHERE id=?');$q->execute([$title,$slug,$excerpt,$body,$image,$author,$status,$sort,$id]);}else{$q=db()->prepare('INSERT INTO content(type,title,slug,excerpt,body,image,author,status,sort_order) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$type,$title,$slug,$excerpt,$body,$image,$author,$status,$sort]);}flash('Content saved.');redirect(url('admin/content.php?type='.$type));}catch(PDOException $e){flash('Save failed. Check that the URL slug is unique.');redirect(url('admin/content.php?type='.$type));}}
$msg=$_SESSION['_flash']??'';unset($_SESSION['_flash']);if(!$id){$q=db()->prepare('SELECT * FROM content WHERE type=? ORDER BY sort_order,title');$q->execute([$type]);$items=$q->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Content manager</title><link rel="stylesheet" href="<?=e(url('assets/css/admin.css'))?>"><link rel="icon" type="image/svg+xml" href="<?=e(url('favicon.svg'))?>"></head><body><div class="shell"><?php require __DIR__.'/_nav.php';?><main><div class="top"><div><small>CONTENT MANAGEMENT</small><h1><?=e($id?'Edit content':$types[$type])?></h1></div><a href="<?=e(url('admin/content.php?type='.$type.'&new=1'))?>">＋ Add new</a></div><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?>
<?php if($id||isset($_GET['new'])):?><form method="post" class="panel editor"><?=csrf_field()?><label>Title<input name="title" required value="<?=e($item['title']??'')?>"></label><label>URL slug<input name="slug" value="<?=e($item['slug']??'')?>"></label><label>Short description<textarea name="excerpt" rows="2"><?=e($item['excerpt']??'')?></textarea></label><label>Content body <small>HTML headings, paragraphs, lists and links supported.</small><textarea name="body" rows="14"><?=e($item['body']??'')?></textarea></label><label>Featured image URL<input name="image" id="image-url" value="<?=e($item['image']??'')?>"></label><div class="upload"><input type="file" id="content-file" accept="image/jpeg,image/png,image/webp,image/gif"><button type="button" id="content-upload" class="secondary">Upload image</button><span id="upload-status"></span></div><label>Author / reviewer name<input name="author" value="<?=e($item['author']??'')?>"></label><div class="two"><label>Status<select name="status"><option value="published" <?=($item['status']??'published')==='published'?'selected':''?>>Published</option><option value="draft" <?=($item['status']??'')==='draft'?'selected':''?>>Draft</option></select></label><label>Display order<input type="number" name="sort_order" value="<?=e((string)($item['sort_order']??0))?>"></label></div><button class="primary">Save content</button><a class="secondary" href="<?=e(url('admin/content.php?type='.$type))?>">Cancel</a></form>
<?php else:?><div class="tabs"><?php foreach($types as $k=>$v):?><a class="<?=$type===$k?'active':''?>" href="<?=e(url('admin/content.php?type='.$k))?>"><?=e($v)?></a><?php endforeach;?></div><section class="panel"><div class="table-wrap"><table><tr><th>Title</th><th>Slug</th><th>Status</th><th>Updated</th></tr><?php foreach($items as $r):?><tr><td><a href="<?=e(url('admin/content.php?type='.$type.'&id='.$r['id']))?>"><?=e($r['title'])?></a><small><?=e($r['excerpt'])?></small></td><td><?=e($r['slug'])?></td><td><?=e($r['status'])?></td><td><?=e(date('M j, Y',strtotime($r['updated_at'])))?></td></tr><?php endforeach;?></table></div></section><?php endif;?></main></div><script>const up=document.getElementById('content-upload');if(up)up.onclick=async()=>{let f=document.getElementById('content-file').files[0],s=document.getElementById('upload-status');if(!f){s.textContent='Choose an image';return;}let d=new FormData();d.append('image',f);d.append('_csrf',<?=json_encode(csrf_token())?>);s.textContent='Uploading…';try{let r=await fetch(<?=json_encode(url('admin/upload.php'))?>,{method:'POST',body:d}),j=await r.json();if(!r.ok)throw Error(j.error);document.getElementById('image-url').value=j.url;s.textContent='Uploaded';}catch(e){s.textContent=e.message;}};</script></body></html>